// --- VERSION 1.2.0 ---
// - Implement smart PID grouping using log-scale clustering to preserve high-fidelity sensor data
// - Move Calculated Load Value to primary scale by default
// - Improved chart stability and ghosting fixes using React keys and instance management
// - Gradual scale transitions using Chart.js animations
// - Optimized side-assignment using buffer data to prevent jitter during navigation

import React, { useMemo, useRef, useEffect, useState, useCallback } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, LogarithmicScale, PointElement, LineElement, Title, Tooltip, Legend
} from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom';
import PIDSelector from '../shared/PIDSelector';
import SamplingIndicator from '../shared/SamplingIndicator';
import { sampleData } from '../../utils/samplingUtils';
import { getDefaultVisibleRange } from '../../utils/rangeUtils';

ChartJS.register(CategoryScale, LinearScale, LogarithmicScale, PointElement, LineElement, Title, Tooltip, Legend, zoomPlugin);

// Function to determine if values need logarithmic scaling
function needsLogScale(values) {
  const validValues = values.filter(v => typeof v === 'number' && v > 0);
  if (validValues.length === 0) return false;

  const min = Math.min(...validValues);
  const max = Math.max(...validValues);

  // Use log scale if range spans more than 2 orders of magnitude
  return (max / min) > 100;
}

// Smart grouping function using log-based clustering to separate disparate scales
function groupPIDsByScale(selectedPIDs, data) {
  const activePIDs = selectedPIDs
    .map((pid, idx) => ({ pid, idx }))
    .filter(p => p.pid && p.pid !== 'none');

  if (activePIDs.length <= 1) {
    return { primary: activePIDs, secondary: [] };
  }

  // Calculate max value for each PID in the data window for clustering
  const pidStats = activePIDs.map(p => {
    const values = data.map(row => row?.[p.pid]).filter(v => typeof v === 'number');
    const maxVal = values.length > 0 ? Math.max(...values) : 0;
    return { ...p, max: maxVal };
  });

  // Sort by max value to find the biggest "jump" in scale
  const sorted = [...pidStats].sort((a, b) => a.max - b.max);

  let splitIdx = 0;
  let maxGap = -1;

  // Find the largest logarithmic gap between consecutive PIDs
  // This effectively separates high-fidelity/low-range sensors (like O2) from high-range ones
  for (let i = 0; i < sorted.length - 1; i++) {
    const val1 = Math.max(0.1, sorted[i].max);
    const val2 = Math.max(0.1, sorted[i+1].max);
    const gap = Math.log10(val2) - Math.log10(val1);

    if (gap > maxGap) {
      maxGap = gap;
      splitIdx = i;
    }
  }

  // If the biggest gap is small, keep everything on one scale
  if (maxGap < 0.5) {
    return { primary: activePIDs, secondary: [] };
  }

  const secondary = sorted.slice(0, splitIdx + 1);
  const primary = sorted.slice(splitIdx + 1);

  return { primary, secondary };
}

// Non-linear RPM scaling function
function scaleRPM(val) {
  if (typeof val !== 'number') return val;
  if (val <= 1000) {
    return val / 10;
  } else if (val <= 4000) {
    return 100 + (val - 1000) / 100;
  } else {
    return 130 + (val - 4000) / 10;
  }
}

export default function TripChart({
  log,
  logs = [], // New prop for comparison mode
  mode = 'single', // 'single' or 'comparison'
  selectedPIDs = [],
  onPIDChange = () => {},
  chartColors = [],
  visibleRange = { min: 0, max: 0 },
  setVisibleRange = () => {},
  onChartZoom = () => {}
}) {
  const chartRef = useRef(null);
  const [isZoomed, setIsZoomed] = useState(false);
  const [key, setKey] = useState(0); // Force re-render key to prevent ghosting

  // Force chart recreation on critical changes to prevent ghosting/canvas issues
  useEffect(() => {
    setKey(prev => prev + 1);
  }, [log?.data?.length, mode]);

  // Determine reference data based on mode
  const referenceLog = useMemo(() => {
    if (mode === 'comparison') {
      return logs.length > 0 ? logs[0] : null;
    }
    return log;
  }, [log, logs, mode]);

  const dataRef = useMemo(() => referenceLog?.data || [], [referenceLog]);
  const colsRef = useMemo(() => referenceLog?.columns || [], [referenceLog]);

  const windowData = useMemo(() => {
    const min = Math.max(0, visibleRange?.min ?? 0);
    const max = Math.min((dataRef.length - 1), visibleRange?.max ?? 0);
    if (dataRef.length === 0 || max < min) return [];
    return dataRef.slice(min, max + 1);
  }, [dataRef, visibleRange]);

  // Use a 5x buffer window for grouping and scaling stability
  const bufferData = useMemo(() => {
    const size = (visibleRange?.max ?? 0) - (visibleRange?.min ?? 0);
    const bufferSize = Math.floor(size * 5);
    const bufferMin = Math.max(0, (visibleRange?.min ?? 0) - bufferSize);
    const bufferMax = Math.min(dataRef.length - 1, (visibleRange?.max ?? 0) + bufferSize);
    return dataRef.slice(bufferMin, bufferMax + 1);
  }, [dataRef, visibleRange]);

  // Generate time labels based on elapsed time from start
  const timeLabels = useMemo(() => {
    if (windowData.length === 0) return [];
    const startTs = Number(dataRef[0]?.timestamp ?? 0);

    return windowData.map(row => {
      const currentTs = Number(row?.timestamp ?? 0);
      const elapsedMs = currentTs - startTs;
      const elapsedSec = Math.max(0, Math.floor(elapsedMs / 1000));
      const hours = Math.floor(elapsedSec / 3600);
      const minutes = Math.floor((elapsedSec % 3600) / 60);
      const seconds = elapsedSec % 60;

      return hours > 0 
        ? `${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
        : `${minutes}:${seconds.toString().padStart(2, '0')}`;
    });
  }, [windowData, dataRef]);

  // Group PIDs and prepare chart data
  const { chartData, useSecondaryScale } = useMemo(() => {
    const datasets = [];
    let hasSecondaryScale = false;

    if (mode === 'comparison') {
      const targetPID = selectedPIDs.find(p => p && p !== 'none');
      if (targetPID && logs.length > 0) {
        logs.forEach((currentLog, idx) => {
          const logData = currentLog.data || [];
          const min = Math.max(0, visibleRange?.min ?? 0);
          const max = Math.min((logData.length - 1), visibleRange?.max ?? 0);

          let points = [];
          if (max >= min) {
             points = logData.slice(min, max + 1).map(row => {
               const val = row?.[targetPID];
               return (targetPID === 'engine_rpm') ? scaleRPM(val) : val;
             });
          }

          datasets.push({
            label: `${currentLog.name || `Log ${currentLog.id}`} - ${targetPID}`,
            data: points,
            borderColor: chartColors[idx] || '#38BDF8',
            backgroundColor: chartColors[idx] || '#38BDF8',
            pointRadius: 0,
            borderWidth: 2,
            tension: 0.4,
            yAxisID: 'y'
          });
        });
      }
    } else {
      // Use bufferData for side-assignment to prevent jitter
      const pidGroups = groupPIDsByScale(selectedPIDs, bufferData);
      hasSecondaryScale = pidGroups.secondary.length > 0;

      // Process primary scale PIDs (solid lines)
      pidGroups.primary.forEach(({ pid, idx }) => {
        let points = windowData.map(row => {
          const val = row?.[pid];
          if (pid === 'engine_rpm') return scaleRPM(val);
          return val;
        });

        datasets.push({
          label: pid === 'engine_rpm' ? 'Engine RPM (Non-linear)' : pid,
          data: points,
          borderColor: chartColors[idx] || '#38BDF8',
          backgroundColor: chartColors[idx] || '#38BDF8',
          pointRadius: 0,
          borderWidth: 2,
          tension: 0.4,
          yAxisID: 'y',
          spanGaps: true
        });
      });

      // Process secondary scale PIDs (dashed lines)
      pidGroups.secondary.forEach(({ pid, idx }) => {
        let points = windowData.map(row => row?.[pid]);
        datasets.push({
          label: pid,
          data: points,
          borderColor: chartColors[idx] || '#38BDF8',
          backgroundColor: chartColors[idx] || '#38BDF8',
          pointRadius: 0,
          borderWidth: 2,
          borderDash: [5, 5], 
          tension: 0.4,
          yAxisID: 'y1',
          spanGaps: true
        });
      });
    }

    return {
      chartData: { labels: timeLabels, datasets },
      useSecondaryScale: hasSecondaryScale
    };
  }, [windowData, bufferData, selectedPIDs, chartColors, timeLabels, mode, logs, visibleRange]);

  // Chart options with dynamic scaling
  const chartOptions = useMemo(() => {
    let primaryValues = [];
    let secondaryValues = [];

    if (mode === 'comparison') {
       const targetPID = selectedPIDs.find(p => p && p !== 'none');
       if (targetPID) {
         primaryValues = logs.flatMap(l => {
            const d = l.data || [];
            const min = Math.max(0, (visibleRange?.min ?? 0));
            const max = Math.min(d.length - 1, (visibleRange?.max ?? 0));
            if (max < min) return [];
            return d.slice(min, max + 1).map(r => {
              const val = r?.[targetPID];
              return (targetPID === 'engine_rpm') ? scaleRPM(val) : val;
            }).filter(v => typeof v === 'number');
         });
       }
    } else {
        const pidGroups = groupPIDsByScale(selectedPIDs, bufferData);
        primaryValues = pidGroups.primary
          .flatMap(({ pid }) => bufferData.map(r => {
             const val = r?.[pid];
             if (pid === 'engine_rpm') return scaleRPM(val);
             return val;
          }).filter(v => typeof v === 'number'));

        secondaryValues = pidGroups.secondary
          .flatMap(({ pid }) => bufferData.map(r => r?.[pid]).filter(v => typeof v === 'number'));
    }

    const scales = {
      x: { 
        ticks: { color: '#9CA3AF' },
        title: { display: true, text: 'Elapsed Time', color: '#9CA3AF' }
      },
      y: {
        type: needsLogScale(primaryValues) ? 'logarithmic' : 'linear',
        position: 'left',
        ticks: { color: '#9CA3AF' },
        title: { display: true, text: 'Primary Scale', color: '#9CA3AF' }
      }
    };

    if (useSecondaryScale && mode !== 'comparison') {
      scales.y1 = {
        type: needsLogScale(secondaryValues) ? 'logarithmic' : 'linear',
        position: 'right',
        ticks: { color: '#9CA3AF' },
        title: { display: true, text: 'Secondary Scale', color: '#9CA3AF' },
        grid: { drawOnChartArea: false }
      };
    }

    return {
      responsive: true,
      maintainAspectRatio: false,
      animation: {
        duration: 500, // Gradual transition for scale changes
        easing: 'easeInOutQuart'
      },
      interaction: { intersect: false, mode: 'index' },
      plugins: {
        legend: { display: true, labels: { color: '#9CA3AF' } },
        zoom: {
          pan: {
            enabled: true,
            mode: 'x',
            onPan: ({ chart }) => {
              const xScale = chart.scales.x;
              const newRange = {
                min: Math.max(0, Math.floor(xScale.min) + (visibleRange?.min ?? 0)),
                max: Math.min(dataRef.length - 1, Math.ceil(xScale.max) + (visibleRange?.min ?? 0))
              };
              setVisibleRange(newRange);
              onChartZoom?.(newRange);
              setIsZoomed(true);
            }
          },
          zoom: {
            wheel: { enabled: false }, 
            pinch: { enabled: true },
            mode: 'x',
            onZoom: ({ chart }) => {
              const xScale = chart.scales.x;
              const newRange = {
                min: Math.max(0, Math.floor(xScale.min) + (visibleRange?.min ?? 0)),
                max: Math.min(dataRef.length - 1, Math.ceil(xScale.max) + (visibleRange?.min ?? 0))
              };
              setVisibleRange(newRange);
              onChartZoom?.(newRange);
              setIsZoomed(true);
            }
          }
        },
        tooltip: {
          callbacks: {
            title: (items) => `Time: ${items[0]?.label || ''}`
          }
        }
      },
      scales
    };
  }, [windowData, bufferData, selectedPIDs, useSecondaryScale, visibleRange, dataRef, setVisibleRange, onChartZoom, mode, logs, chartColors]);

  // Handle zoom buttons
  const handleZoom = useCallback((minutes) => {
    if (minutes === 'reset') {
      const fullRange = { min: 0, max: dataRef.length - 1 };
      setVisibleRange(fullRange);
      onChartZoom?.(fullRange);
      setIsZoomed(false);
      if (chartRef.current) chartRef.current.resetZoom();
      return;
    }
    const range = getDefaultVisibleRange(dataRef, minutes * 60);
    setVisibleRange(range);
    onChartZoom?.(range);
    setIsZoomed(true);
  }, [dataRef, setVisibleRange, onChartZoom]);

  const totalDuration = useMemo(() => {
    if (dataRef.length < 2) return 0;
    const start = Number(dataRef[0]?.timestamp ?? 0);
    const end = Number(dataRef[dataRef.length - 1]?.timestamp ?? 0);
    return (end - start) / 1000;
  }, [dataRef]);

  // Handle pan buttons
  const handlePan = useCallback((direction) => {
    const totalLength = dataRef.length;
    const size = (visibleRange?.max ?? 0) - (visibleRange?.min ?? 0);
    const shift = Math.floor(size / 10); 
    let min = visibleRange?.min ?? 0;
    if (direction === 'left') min = Math.max(0, min - shift);
    else if (direction === 'right') min = Math.min(totalLength - size, min + shift);
    const newRange = { min, max: min + size };
    setVisibleRange(newRange);
    onChartZoom?.(newRange);
  }, [dataRef.length, visibleRange, setVisibleRange, onChartZoom]);

  // Handle scrollbar dragging
  const handleScrollbarClick = useCallback((e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const totalLength = dataRef.length;
    const size = (visibleRange?.max ?? 0) - (visibleRange?.min ?? 0);
    let newMin = Math.floor((x / rect.width) * totalLength) - Math.floor(size / 2);
    newMin = Math.max(0, Math.min(totalLength - size - 1, newMin));
    const newRange = { min: newMin, max: newMin + size };
    setVisibleRange(newRange);
    onChartZoom?.(newRange);
  }, [dataRef.length, visibleRange, setVisibleRange, onChartZoom]);

  const { scrollWidthPercent, scrollLeftPercent } = useMemo(() => {
    const total = dataRef.length;
    const size = (visibleRange?.max ?? 0) - (visibleRange?.min ?? 0);
    const widthPct = total > 0 ? Math.max((size / total) * 100, 2) : 100;
    const leftPct = total > 0 ? ((visibleRange?.min ?? 0) / total) * 100 : 0;
    return { scrollWidthPercent: widthPct, scrollLeftPercent: leftPct };
  }, [dataRef.length, visibleRange]);

  const isFullyZoomedOut = (visibleRange?.min ?? 0) === 0 && (visibleRange?.max ?? 0) === dataRef.length - 1;

  return (
    <div className="bg-gray-800 rounded-lg shadow-xl p-4 space-y-3">
      <div className="flex items-center justify-between flex-wrap gap-2">
        {selectedPIDs.map((pid, index) => (
          <PIDSelector
            key={index}
            color={chartColors[index] || '#38BDF8'}
            options={colsRef}
            selectedValue={pid}
            onChange={(value) => onPIDChange(index, value)}
          />
        ))}
      </div>

      <div className="flex items-center space-x-3 text-sm">
        <div className="flex items-center space-x-2">
          <label className="text-gray-400">View Window:</label>
          <select 
            className="bg-gray-700 text-gray-100 px-2 py-1 rounded border border-gray-600 focus:outline-none focus:border-cyan-400"
            onChange={(e) => handleZoom(Number(e.target.value))}
            value=""
          >
            <option value="" disabled>Select range...</option>
            {[1, 2, 3, 5, 10, 15, 20, 30, 45, 60].filter(m => m * 60 <= totalDuration).map(m => (
              <option key={m} value={m}>{m} min</option>
            ))}
          </select>
        </div>
        <button 
          onClick={() => handleZoom('reset')} 
          disabled={isFullyZoomedOut}
          className={`px-3 py-1 rounded transition-colors ${
            isFullyZoomedOut ? 'bg-gray-600 text-gray-500' : 'bg-gray-700 hover:bg-gray-600 text-cyan-400 border border-gray-600'
          }`}
        >
          Full View
        </button>
      </div>

      <div className="h-[56vh] cursor-crosshair">
        <Line key={key} ref={chartRef} options={chartOptions} data={chartData} />
      </div>

      <div className="flex items-center space-x-2">
        <button
          onClick={() => handlePan('left')}
          disabled={(visibleRange?.min ?? 0) <= 0}
          className="px-3 py-1 rounded transition-colors bg-gray-700 hover:bg-gray-600 text-gray-300 disabled:opacity-50"
        >
          ←
        </button>
        <div 
          className="flex-1 h-4 bg-gray-900/50 rounded-full relative overflow-hidden cursor-pointer border border-gray-700"
          onClick={handleScrollbarClick}
        >
          <div
            className="absolute top-0 h-4 bg-gradient-to-r from-cyan-600 to-blue-500 rounded-full transition-all duration-200"
            style={{ width: `${scrollWidthPercent}%`, left: `${scrollLeftPercent}%` }}
          />
        </div>
        <button
          onClick={() => handlePan('right')}
          disabled={(visibleRange?.max ?? 0) >= dataRef.length - 1}
          className="px-3 py-1 rounded transition-colors bg-gray-700 hover:bg-gray-600 text-gray-300 disabled:opacity-50"
        >
          →
        </button>
      </div>

      {useSecondaryScale && (
        <div className="text-xs text-gray-400 text-center">
          Solid lines: Left scale | Dashed lines: Right scale
        </div>
      )}
    </div>
  );
}
